local mapper = mapper
local config_ledfw = "ledfw"

-- uci.ledfw
mapper("uci_1to1").registerConfigMap(config_ledfw)

-- uci.ledfw.internet.
local ledfw_internet = {
    config = config_ledfw,
    section = "internet",
    type = "service",
    options = {
        "check", "itf"
    }
}

mapper("uci_1to1").registerSimpleMap(ledfw_internet)

-- uci.ledfw.iptv.
local ledfw_iptv = {
    config = config_ledfw,
    section = "iptv",
    type = "service",
    options = {
        "check", "itf"
    }
}

mapper("uci_1to1").registerSimpleMap(ledfw_iptv)

-- uci.ledfw.voip.
local ledfw_voip = {
    config = config_ledfw,
    section = "voip",
    type = "service",
    options = {
        "check", "itf"
    }
}

mapper("uci_1to1").registerSimpleMap(ledfw_voip)

-- uci.ledfw.timeout.
local ledfw_timeout = {
    config = config_ledfw,
    section = "timeout",
    type = "timeout",
    options = { "ms" },
}

mapper("uci_1to1").registerSimpleMap(ledfw_timeout)

